#!/usr/bin/env bash
# Question 3: Unhealthy Pods in ${Q3_NS}-ops. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

rm -rf /opt/course/audit
mkdir -p /opt/course/audit
chown -R ubuntu:ubuntu /opt/course
kubectl delete namespace "${Q3_NS}-ops" --ignore-not-found --wait=true >/dev/null
kubectl create namespace "${Q3_NS}-ops" >/dev/null 2>&1 || kubectl get namespace "${Q3_NS}-ops" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q3_NS}-ops' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
names=($(shuf -e checkout-api pricing-sync email-worker search-api fraud-check audit-export nightly-report -n 7))
bad=$(shuf -e nginx:1.27-alpinee registry.lab.internal/payments/api:2.4 httpd:2.4-alpne -n 1)
kubectl apply -f - <<EOF >/dev/null
apiVersion: v1
kind: Pod
metadata: { name: ${names[0]}, namespace: ${Q3_NS}-ops }
spec:
  terminationGracePeriodSeconds: 1
  containers:
    - name: app
      image: busybox:1.36
      command: ["sleep", "infinity"]
---
apiVersion: v1
kind: Pod
metadata: { name: ${names[1]}, namespace: ${Q3_NS}-ops }
spec:
  terminationGracePeriodSeconds: 1
  containers:
    - name: app
      image: busybox:1.36
      command: ["sleep", "infinity"]
---
apiVersion: v1
kind: Pod
metadata: { name: ${names[2]}, namespace: ${Q3_NS}-ops }
spec:
  terminationGracePeriodSeconds: 1
  containers:
    - name: app
      image: $bad
---
apiVersion: v1
kind: Pod
metadata: { name: ${names[3]}, namespace: ${Q3_NS}-ops }
spec:
  terminationGracePeriodSeconds: 1
  containers:
    - name: app
      image: busybox:1.36
      command: ["sh", "-c", "echo missing DATABASE_URL; exit 1"]
---
apiVersion: v1
kind: Pod
metadata: { name: ${names[4]}, namespace: ${Q3_NS}-ops }
spec:
  terminationGracePeriodSeconds: 1
  nodeSelector: { disktype: nvme }
  containers:
    - name: app
      image: busybox:1.36
      command: ["sleep", "infinity"]
---
apiVersion: v1
kind: Pod
metadata: { name: ${names[5]}, namespace: ${Q3_NS}-ops }
spec:
  terminationGracePeriodSeconds: 1
  initContainers:
    - name: wait-for-db
      image: busybox:1.36
      command: ["sh", "-c", "until nslookup db; do sleep 5; done"]
  containers:
    - name: app
      image: busybox:1.36
      command: ["sleep", "infinity"]
---
apiVersion: v1
kind: Pod
metadata: { name: ${names[6]}, namespace: ${Q3_NS}-ops }
spec:
  terminationGracePeriodSeconds: 1
  restartPolicy: Never
  containers:
    - name: report
      image: busybox:1.36
      command: ["sh", "-c", "echo report done"]
EOF
kubectl -n "${Q3_NS}-ops" wait --for=condition=Ready "pod/${names[0]}" "pod/${names[1]}" --timeout=180s >/dev/null
kubectl -n "${Q3_NS}-ops" wait --for=jsonpath='{.status.phase}'=Succeeded "pod/${names[6]}" --timeout=180s >/dev/null
# Start from a settled state: the pull has failed and the scheduler has given up on the Pending Pod.
for _ in $(seq 1 60); do
  [[ -n "$(kubectl -n ${Q3_NS}-ops get pods -o json | jq -r '.items[] | select([.status.containerStatuses[]? | .state.waiting.reason // ""] | any(test("ErrImagePull|ImagePullBackOff"))) | .spec.containers[].image')" && -n "$(kubectl -n ${Q3_NS}-ops get pods -o json | jq -r '.items[] | select([.status.conditions[]? | select(.type == "PodScheduled" and .status == "False")] | length > 0) | .metadata.name')" ]] && break
  sleep 2
done
: "${Q3_NS}"
